import calendar
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    tokens = rule.split()
    freq = tokens[0]
    k = int(tokens[1])
    res = []

    wd_map = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}

    if freq == "DAILY":
        curr = start_date
        step = timedelta(days=k)
        while len(res) < count:
            res.append(curr.isoformat())
            curr += step

    elif freq == "WEEKLY":
        target_wds = sorted(wd_map[w] for w in tokens[2].split(","))
        # Monday of week 0 containing start_date
        monday_0 = start_date - timedelta(days=start_date.weekday())
        week_idx = 0
        while len(res) < count:
            week_monday = monday_0 + timedelta(weeks=week_idx)
            for wd in target_wds:
                candidate = week_monday + timedelta(days=wd)
                if candidate >= start_date:
                    res.append(candidate.isoformat())
                    if len(res) == count:
                        break
            week_idx += k

    elif freq == "MONTHLY":
        if len(tokens) == 3:
            # MONTHLY K D
            target_d = int(tokens[2])
            month_idx = 0
            while len(res) < count:
                total_months = (
                    start_date.year * 12 + (start_date.month - 1) + month_idx
                )
                year = total_months // 12
                month = total_months % 12 + 1
                days_in_month = calendar.monthrange(year, month)[1]

                day = days_in_month if target_d == -1 else target_d
                if 1 <= day <= days_in_month:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        res.append(candidate.isoformat())
                month_idx += k

        else:
            # MONTHLY K N WD
            target_n = int(tokens[2])
            target_wd = wd_map[tokens[3]]
            month_idx = 0
            while len(res) < count:
                total_months = (
                    start_date.year * 12 + (start_date.month - 1) + month_idx
                )
                year = total_months // 12
                month = total_months % 12 + 1
                days_in_month = calendar.monthrange(year, month)[1]

                matching_days = [
                    d
                    for d in range(1, days_in_month + 1)
                    if date(year, month, d).weekday() == target_wd
                ]

                candidate_day = None
                if target_n == -1:
                    candidate_day = matching_days[-1]
                elif 1 <= target_n <= len(matching_days):
                    candidate_day = matching_days[target_n - 1]

                if candidate_day is not None:
                    candidate = date(year, month, candidate_day)
                    if candidate >= start_date:
                        res.append(candidate.isoformat())
                month_idx += k

    elif freq == "YEARLY":
        mm, dd = map(int, tokens[2].split("-"))
        year_idx = 0
        while len(res) < count:
            year = start_date.year + year_idx
            try:
                candidate = date(year, mm, dd)
                if candidate >= start_date:
                    res.append(candidate.isoformat())
            except ValueError:
                pass
            year_idx += k

    return res
